 public static function key(string $source):string{return'application_setup_'.substr(hash('sha256',$source),0,24);}
 public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$t)$out[self::key($s)]=$en?$t:$s;return$out;}
 public static function text(string $source,array $messages,array $values=[]):string{$value=$messages[self::key($source)]??ManualApplicationMessages::text($source,$messages);foreach($values as$key=>$part)$value=str_replace('{'.$key.'}',(string)$part,$value);return$value;}
 public static function failure(string $source,array $messages):string{if($source==='Ursprüngliche Einrichtung und Vorgangskennung prüfen.')return self::text('Dieses Formular ist nicht mehr gültig. Öffne die aktuelle Einrichtung und prüfe deine Angaben erneut.',$messages);if(isset(self::ENGLISH[$source]))return self::text($source,$messages);return ManualApplicationMessages::failure($source,$messages);}
